const API_URL = "https://secrets-api.appbrewery.com";
const yourUsername = "<username>";
const yourPassword = "<password>";
const yourAPIKey = "<api key>";
const yourBearerToken = "<token>";

app.get("/noAuth", async (req, res) => {
  try {
    const result = await axios.get(API_URL + "/random");
    res.render("index.ejs", { content: JSON.stringify(result.data) });
  } catch (error) { res.status(404).send(error.message); }
});

app.get("/basicAuth", async (req, res) => {
  try {
    const result = await axios.get(API_URL + "/all?page=2", {
      auth: { username: yourUsername, password: yourPassword },
    });
    res.render("index.ejs", { content: JSON.stringify(result.data) });
  } catch (error) { res.status(404).send(error.message); }
});

app.get("/apiKey", async (req, res) => {
  try {
    const result = await axios.get(API_URL + "/filter", {
      params: { score: 5, apiKey: yourAPIKey },
    });
    res.render("index.ejs", { content: JSON.stringify(result.data) });
  } catch (error) { res.status(404).send(error.message); }
});

const config = { headers: { Authorization: `Bearer ${yourBearerToken}` } };

app.get("/bearerToken", async (req, res) => {
  try {
    const result = await axios.get(API_URL + "/secrets/2", config);
    res.render("index.ejs", { content: JSON.stringify(result.data) });
  } catch (error) { res.status(404).send(error.message); }
});
